import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import org.traccar.protocol.GalileoProtocolDecoder;

public class GalileoProtocolDecoderTest {

    @Test
    public void testDecode_Position() {
        // Arrange
        byte[] data = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
        Position position = new Position(10.5f, 20.7f, Calendar.getInstance().getTime());
        Map<String, Object> networkMessage = new HashMap<>();
        networkMessage.put("position", position);
        NetworkMessage msg = new NetworkMessage(data, networkMessage);

        // Act
        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());

        // Assert
        assertEquals("Position", decoder.decode(msg));
    }

    @Test
    public void testDecode_NetworkMessage() {
        // Arrange
        byte[] data = new byte[]{0x00, 0x01, 0x02, 0x03};
        NetworkMessage msg = new NetworkMessage(data);

        // Act
        GalileoProtocolDecoder decoder = new GalileoProtocolDecoder(new Protocol());

        // Assert
        assertEquals("NetworkMessage", decoder.decode(msg));
    }

    @Test
    public void testDecode_InvalidData() {
        // Arrange
        byte[] data = new byte[]{0x00, 0x01, 0x02, 0x03, 0x04};
        NetworkMessage msg = new NetworkMessage(data);

        // Act and Assert
        AssertionError exception = assertThrows(io.netty.buffer.ByteBufUtil.InvalidByteBufException.class, () -> decoder.decode(msg));
        assertEquals("Invalid ByteBuf", exception.getMessage());
    }

